import UIKit

class ProfileViewController: BaseViewController {
    override func viewDidLoad() { super.viewDidLoad(); title = "Profile"; stack.addArrangedSubview(heading("Player profile", subtitle: "Local profile for launcher personalization.")); let avatar = CardView(title: "◉  \(Preferences.username)", body: "Offline profile · No official account connected\nSkin preview is unavailable until an image is imported.", icon: "👤"); stack.addArrangedSubview(avatar); let edit = ActionButton("Edit local username"); edit.addTarget(self, action: #selector(editName), for: .touchUpInside); stack.addArrangedSubview(edit); stack.addArrangedSubview(card("Official account", body: "This build does not implement Mojang or Microsoft authentication. It does not collect or store account credentials.", icon: "🔒")); stack.addArrangedSubview(card("Offline mode", body: "The displayed name is a local label only. It does not create an authenticated Minecraft session or enable game play.", icon: "◌")) }
    @objc private func editName() { let a = UIAlertController(title: "Local username", message: "Choose a name to display in Blockside.", preferredStyle: .alert); a.addTextField { $0.text = Preferences.username; $0.autocapitalizationType = .words }; a.addAction(UIAlertAction(title: "Cancel", style: .cancel)); a.addAction(UIAlertAction(title: "Save", style: .default) { _ in let value = a.textFields?.first?.text?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""; Preferences.username = value.isEmpty ? "Player" : value; self.showMessage("Saved", "The local display name will appear when the home screen is reopened.") }); present(a, animated: true) }
}
